"""The control-flow IR object model.

The IR is intentionally tiny and directly traversable::

    Module
      Function            (signature, local slots, basic blocks)
        Block             (phi nodes, ordered instructions, one terminator)
          Phi             (SSA only; one incoming value per predecessor)
          Instruction     (Const / Copy / BinOp / Call, all write a dest)
          Terminator      (Return / Jump / Branch)

Two flavors of module exist:

* non-SSA (produced by :func:`lower_module`): value references are
  :class:`Temp` -- numbered temporaries produced by instructions -- and
  :class:`Slot`, numbered mutable local storage (parameters and ``let``
  variables).  Temporaries are mostly single assignment; the sole exception
  is the result temporary of a short-circuit boolean operation, which is
  written once on each participating path, as is natural in non-SSA form.
* SSA (produced by :func:`to_ssa`): every parameter and every instruction
  result is a unique definition, slots never appear, and control-flow joins
  carry :class:`Phi` nodes listed before the block's ordinary instructions.

Both flavors reuse the same node classes; a module's ``ssa`` flag (and each
function's) says which one it is.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional, Union


@dataclass(frozen=True)
class Temp:
    id: int
    type: str

    def __str__(self) -> str:
        return f"%t{self.id}"


@dataclass(frozen=True)
class Slot:
    """A mutable local slot (parameter or ``let`` variable)."""

    id: int
    type: str

    def __str__(self) -> str:
        return f"%v{self.id}"


ValueRef = Union[Temp, Slot]


@dataclass
class Const:
    dest: Temp
    value: Union[int, bool]

    @property
    def op(self) -> str:
        return "const"


@dataclass
class Copy:
    dest: Union[Temp, Slot]
    src: ValueRef

    @property
    def op(self) -> str:
        return "copy"


@dataclass
class BinOp:
    dest: Temp
    operator: str
    left: ValueRef
    right: ValueRef
    kind: str  # "arith" or "compare"
    type: str  # result type

    @property
    def op(self) -> str:
        return self.kind


@dataclass
class Call:
    dest: Temp
    name: str
    args: list[ValueRef]
    type: str

    @property
    def op(self) -> str:
        return "call"


Instruction = Union[Const, Copy, BinOp, Call]


@dataclass(eq=False)
class Phi:
    """An SSA phi function: merges definitions from predecessor blocks.

    ``entries`` maps a predecessor :class:`Block` to the value that is live
    on that edge.  Entries are kept sorted by predecessor label whenever a
    module is emitted by :func:`to_ssa`; only reachable predecessors occur.
    """

    dest: Temp
    entries: dict["Block", ValueRef] = field(default_factory=dict)

    @property
    def op(self) -> str:
        return "phi"

    @property
    def type(self) -> str:
        return self.dest.type


@dataclass
class Return:
    value: Optional[ValueRef]

    @property
    def op(self) -> str:
        return "return"


@dataclass
class Jump:
    target: "Block"

    @property
    def op(self) -> str:
        return "jump"


@dataclass
class Branch:
    cond: ValueRef
    true_target: "Block"
    false_target: "Block"

    @property
    def op(self) -> str:
        return "br"


Terminator = Union[Return, Jump, Branch]


@dataclass(eq=False)
class Block:
    id: int
    instructions: list[Instruction] = field(default_factory=list)
    terminator: Optional[Terminator] = None
    # SSA only; empty in non-SSA blocks.  Phi nodes precede the ordinary
    # instructions.
    phis: list[Phi] = field(default_factory=list)

    @property
    def label(self) -> str:
        return f"b{self.id}"

    @property
    def is_terminated(self) -> bool:
        return self.terminator is not None


@dataclass
class Parameter:
    name: str
    slot: Slot
    # SSA only: the unique parameter definition.  None in non-SSA functions,
    # where the parameter is read through ``slot``.
    temp: Optional[Temp] = None


@dataclass
class Function:
    name: str
    params: list[Parameter]
    ret_type: str
    locals: list[Slot]
    blocks: list[Block]
    entry: Block
    ssa: bool = False

    def is_void(self) -> bool:
        return self.ret_type == "void"


@dataclass
class Module:
    functions: list[Function]
    ssa: bool = False

"""Conversion of the non-SSA control-flow IR into pruned SSA form.

The entry point :func:`to_ssa` takes a :class:`Module` produced by
:func:`lower_module` and returns a brand new, traversable and renderable
SSA :class:`Module`; the input module is never mutated.  Feeding an SSA
module back in yields a structurally and textually equivalent copy (no new
phi nodes, unchanged numbering), and any non-:class:`Module` object raises
:class:`TypeError`.

Algorithm (Cytron et al., with pruning)
--------------------------------------
1. Compute reachable blocks, predecessors and the dominator tree from the
   CFG induced by the terminators.
2. Every value definition site (a parameter slot, a slot copy, or a
   possibly multi-written temporary such as a short-circuit result) gets a
   phi at its iterated dominance frontier.
3. A dominator-tree walk renames every definition to a fresh SSA value and
   fills phi entries from the stacks live on each outgoing edge.  Only
   reachable edges are visited, so an unreachable predecessor never appears
   in a phi.
4. Dead (result-unused) and trivial (one distinct incoming value, ignoring
   the phi itself and missing edges) phis are removed to a fixpoint; chains
   and loop self-loops collapse in turn.
5. Values are numbered deterministically per function -- parameters in
   order, then blocks in id order, phis before ordinary instructions -- so
   repeated conversion of the same module is byte-identical and independent
   of set or dict iteration order and object identity.
"""
from .ir_nodes import (
    BinOp,
    Block,
    Branch,
    Call,
    Const,
    Copy,
    Function,
    Jump,
    Module,
    Parameter,
    Phi,
    Return,
    Temp,
)


def to_ssa(module: Module) -> Module:
    """Return an SSA copy of ``module``.

    The input module is left untouched.  A module already in SSA form is
    copied to an equivalent SSA module (same phi nodes, same numbering).

    :raises TypeError: if ``module`` is not a :class:`Module` instance.
    """
    if not isinstance(module, Module):
        raise TypeError(
            f"to_ssa expects a Module, got {type(module).__name__}"
        )
    if getattr(module, "ssa", False):
        return _clone_ssa_module(module)
    return Module(
        [_Converter(func).convert() for func in module.functions], ssa=True
    )


# --------------------------------------------------------------------------
# CFG analysis
# --------------------------------------------------------------------------


def _terminator_edges(block: Block):
    """Return the successor blocks of a block in fixed edge order."""
    term = block.terminator
    if isinstance(term, Jump):
        return [term.target]
    if isinstance(term, Branch):
        return [term.true_target, term.false_target]
    return []


class _CFG:
    def __init__(self, func: Function):
        self.blocks = list(func.blocks)
        self.index = {block: i for i, block in enumerate(self.blocks)}
        self.succs: dict[Block, list[Block]] = {
            block: _terminator_edges(block) for block in self.blocks
        }
        self.reachable = self._reachable_set(func.entry)
        self.preds: dict[Block, list[Block]] = {
            block: [] for block in self.blocks
        }
        for block in self.blocks:
            if block not in self.reachable:
                continue
            for target in self.succs[block]:
                if target in self.reachable:
                    self.preds[target].append(block)

    def _reachable_set(self, entry: Block) -> set[Block]:
        seen = {entry}
        stack = [entry]
        while stack:
            block = stack.pop()
            for target in self.succs[block]:
                if target not in seen:
                    seen.add(target)
                    stack.append(target)
        return seen

    def sort(self, blocks) -> list[Block]:
        """Sort an iterable of blocks by deterministic block index."""
        return sorted(blocks, key=lambda b: self.index[b])


def _reverse_postorder(cfg: _CFG, entry: Block) -> list[Block]:
    order: list[Block] = []
    visited = {entry}
    stack = [(entry, 0)]
    while stack:
        block, pos = stack[-1]
        successors = cfg.succs[block]
        if pos < len(successors):
            stack[-1] = (block, pos + 1)
            target = successors[pos]
            if target in cfg.reachable and target not in visited:
                visited.add(target)
                stack.append((target, 0))
        else:
            order.append(block)
            stack.pop()
    order.reverse()
    return order


def _dominators(cfg: _CFG, entry: Block) -> dict[Block, Block]:
    """Immediate dominators (Cooper-Harvey-Waterman iterative fix point)."""
    rpo = _reverse_postorder(cfg, entry)
    rpo_index = {block: i for i, block in enumerate(rpo)}
    preds_order = {
        block: cfg.sort(p for p in cfg.preds[block] if p in rpo_index)
        for block in rpo
    }

    def intersect(a: Block, b: Block) -> Block:
        while a is not b:
            while rpo_index[a] > rpo_index[b]:
                a = idom[a]
            while rpo_index[b] > rpo_index[a]:
                b = idom[b]
        return a

    idom: dict[Block, Block] = {entry: entry}
    changed = True
    while changed:
        changed = False
        for block in rpo[1:]:
            new_idom = next(p for p in preds_order[block] if p in idom)
            for pred in preds_order[block]:
                if pred is new_idom or pred not in idom:
                    continue
                new_idom = intersect(pred, new_idom)
            if idom.get(block) is not new_idom:
                idom[block] = new_idom
                changed = True
    return idom


def _dominance_frontiers(cfg: _CFG, idom) -> dict[Block, list[Block]]:
    frontiers: dict[Block, set[Block]] = {
        block: set() for block in cfg.reachable
    }
    for block in cfg.sort(cfg.reachable):
        if len(cfg.preds[block]) < 2:
            continue
        for pred in cfg.preds[block]:
            runner = pred
            while runner is not idom[block]:
                frontiers[runner].add(block)
                runner = idom[runner]
    return {block: cfg.sort(nodes) for block, nodes in frontiers.items()}


# --------------------------------------------------------------------------
# Operand helpers (work uniformly on phi entries, instructions, terminators)
# --------------------------------------------------------------------------


def _operands(ins):
    if isinstance(ins, Copy):
        return [ins.src]
    if isinstance(ins, BinOp):
        return [ins.left, ins.right]
    if isinstance(ins, Call):
        return list(ins.args)
    return []


def _map_operands(ins, fn) -> None:
    if isinstance(ins, Copy):
        ins.src = fn(ins.src)
    elif isinstance(ins, BinOp):
        ins.left = fn(ins.left)
        ins.right = fn(ins.right)
    elif isinstance(ins, Call):
        ins.args = [fn(arg) for arg in ins.args]


def _term_operands(term):
    if isinstance(term, Return) and term.value is not None:
        return [term.value]
    if isinstance(term, Branch):
        return [term.cond]
    return []


def _map_term_operands(term, fn) -> None:
    if isinstance(term, Return) and term.value is not None:
        term.value = fn(term.value)
    elif isinstance(term, Branch):
        term.cond = fn(term.cond)


# --------------------------------------------------------------------------
# Per-function conversion
# --------------------------------------------------------------------------


class _Converter:
    def __init__(self, func: Function):
        self.func = func
        self.cfg = _CFG(func)
        self._fresh_counter = 0

    def fresh(self, typ: str) -> Temp:
        temp = Temp(self._fresh_counter, typ)
        self._fresh_counter += 1
        return temp

    def convert(self) -> Function:
        cfg = self.cfg
        entry = self.func.entry
        idom = _dominators(cfg, entry)
        frontiers = _dominance_frontiers(cfg, idom)

        new_blocks = [Block(block.id) for block in cfg.blocks]
        block_map = dict(zip(cfg.blocks, new_blocks))

        # -- definition sites, in original DFS definition order ----------
        param_temp: dict = {}
        defs: dict[object, list[Block]] = {}
        ref_order: dict[object, int] = {}

        def register(ref, block: Block) -> None:
            if ref not in ref_order:
                ref_order[ref] = len(ref_order)
            defs.setdefault(ref, []).append(block)

        for param in self.func.params:
            temp = self.fresh(param.slot.type)
            param_temp[param.slot] = temp
            register(param.slot, entry)

        for block in cfg.blocks:
            if block not in cfg.reachable:
                continue
            for ins in block.instructions:
                register(ins.dest, block)

        # -- phi placeholders at iterated dominance frontiers ------------
        phi_origin: dict[Phi, object] = {}
        block_phis: dict[Block, list[Phi]] = {}
        already: dict[Block, set[object]] = {
            block: set() for block in cfg.reachable
        }
        for ref in sorted(ref_order, key=lambda r: ref_order[r]):
            worklist = list(defs[ref])
            while worklist:
                site = worklist.pop()
                for frontier in frontiers.get(site, ()):
                    if ref in already[frontier]:
                        continue
                    already[frontier].add(ref)
                    phi = Phi(self.fresh(ref.type), {})
                    phi_origin[phi] = ref
                    block_phis.setdefault(frontier, []).append(phi)
                    if not any(s is frontier for s in worklist):
                        worklist.append(frontier)

        for block in block_phis:
            block_phis[block].sort(key=lambda phi: ref_order[phi_origin[phi]])

        # -- renaming over the dominator tree ----------------------------
        stacks: dict[object, list[Temp]] = {
            slot: [temp] for slot, temp in param_temp.items()
        }

        children: dict[Block, list[Block]] = {
            block: [] for block in cfg.reachable
        }
        for block in cfg.sort(cfg.reachable):
            if block is not entry:
                children[idom[block]].append(block)
        for child_list in children.values():
            child_list.sort(key=lambda b: cfg.index[b])

        def top(ref):
            stack = stacks.get(ref)
            return stack[-1] if stack else None

        loose: dict[object, Temp] = {}

        def use(ref):
            mapped = top(ref)
            if mapped is None:
                # Only reached on edges where the name is genuinely
                # undefined; in lowered IR such edges are unreachable, and
                # the placeholder disappears together with its dead phi.
                mapped = loose.get(ref)
                if mapped is None:
                    mapped = self.fresh(ref.type)
                    loose[ref] = mapped
            return mapped

        def rename(old: Block, new: Block) -> None:
            saved = {ref: len(stack) for ref, stack in stacks.items()}

            for phi in block_phis.get(old, ()):
                stacks.setdefault(phi_origin[phi], []).append(phi.dest)

            for ins in old.instructions:
                if isinstance(ins, Copy):
                    # A copy is pure aliasing in SSA: the defined name now
                    # denotes the renamed source value, no instruction (and
                    # no fresh definition) is emitted.  This is also what
                    # lets branches assigning the same value share one SSA
                    # value and keep their merge phi trivial.
                    stacks.setdefault(ins.dest, []).append(use(ins.src))
                    continue
                cloned = self._clone_ins(ins, use)
                new.instructions.append(cloned)
                stacks.setdefault(ins.dest, []).append(cloned.dest)

            new.terminator = self._clone_terminator(old.terminator,
                                                    block_map, use)

            # Fill the phi of every reachable successor: current block is
            # the predecessor supplying top(ref) on this edge.
            for successor in cfg.succs[old]:
                if successor not in cfg.reachable:
                    continue
                for phi in block_phis.get(successor, ()):
                    phi.entries[new] = use(phi_origin[phi])

            for child in children[old]:
                rename(child, block_map[child])

            for ref, length in saved.items():
                del stacks[ref][length:]

        rename(entry, block_map[entry])

        for old, new in block_map.items():
            new.phis = list(block_phis.get(old, ()))
            if old not in cfg.reachable:
                self._clone_unreachable(old, new, block_map)

        new_params = [
            Parameter(param.name, param.slot, param_temp[param.slot])
            for param in self.func.params
        ]
        self._prune(new_blocks)
        self._renumber(new_params, new_blocks)

        return Function(
            self.func.name,
            new_params,
            self.func.ret_type,
            [],
            new_blocks,
            block_map[entry],
            ssa=True,
        )

    # -- cloning -----------------------------------------------------------

    def _clone_ins(self, ins, use):
        if isinstance(ins, Const):
            return Const(self.fresh(ins.dest.type), ins.value)
        if isinstance(ins, Copy):
            return Copy(self.fresh(ins.dest.type), use(ins.src))
        if isinstance(ins, BinOp):
            return BinOp(
                self.fresh(ins.dest.type), ins.operator,
                use(ins.left), use(ins.right), ins.kind, ins.type,
            )
        return Call(
            self.fresh(ins.dest.type), ins.name,
            [use(arg) for arg in ins.args], ins.type,
        )

    def _clone_terminator(self, term, block_map, use):
        if isinstance(term, Return):
            return Return(None if term.value is None else use(term.value))
        if isinstance(term, Jump):
            return Jump(block_map[term.target])
        if isinstance(term, Branch):
            return Branch(
                use(term.cond),
                block_map[term.true_target],
                block_map[term.false_target],
            )
        return None  # pragma: no cover - lowerer always terminates blocks

    def _clone_unreachable(self, old: Block, new: Block, block_map) -> None:
        """Structural clone for blocks unreachable from the entry.

        ``lower_module`` never emits such blocks; this keeps the transform
        total without inserting phi nodes that no reachable edge feeds.
        """
        local: dict[object, Temp] = {}

        def local_use(ref):
            mapped = local.get(ref)
            if mapped is None:
                mapped = self.fresh(ref.type)
                local[ref] = mapped
            return mapped

        new.phis = []
        new.instructions = []
        for ins in old.instructions:
            if isinstance(ins, Copy):
                local[ins.dest] = local_use(ins.src)
                continue
            cloned = self._clone_ins(ins, local_use)
            local[ins.dest] = cloned.dest
            new.instructions.append(cloned)
        new.terminator = self._clone_terminator(
            old.terminator, block_map, local_use
        )

    # -- phi pruning -------------------------------------------------------

    def _prune(self, blocks: list[Block]) -> None:
        """Remove dead and trivial phi nodes to a fixpoint.

        A phi is *dead* when nothing outside the phi-only reference graph
        reads its result: phi-only cycles (e.g. a loop-carried temporary
        nobody reads) evaporate together.  A phi is *trivial* when its
        incoming values collapse to one distinct value once previously
        removed phis are chased through; a loop self-reference on its own
        result counts as such.  Dead phis are dropped as a batch first,
        then trivial phis one at a time; the two passes alternate until
        neither fires.
        """
        while self._remove_dead_phis(blocks) | self._remove_trivial_phis(
            blocks
        ):
            pass

    def _live_phi_dests(self, blocks: list[Block]) -> set[int]:
        all_phis = [phi for block in blocks for phi in block.phis]

        # Worklist starts from temps consumed by ordinary instructions and
        # terminators; reaching a phi's result marks that phi live and in
        # turn activates the phis feeding it.  A closed phi-only cycle is
        # never seeded and so dies wholesale.
        worklist: list[int] = []
        for block in blocks:
            for ins in block.instructions:
                worklist.extend(id(v) for v in _operands(ins))
            worklist.extend(id(v) for v in _term_operands(block.terminator))

        live: set[int] = set()
        phi_by_dest = {id(phi.dest): phi for phi in all_phis}
        while worklist:
            temp_id = worklist.pop()
            if temp_id in live:
                continue
            live.add(temp_id)
            phi = phi_by_dest.get(temp_id)
            if phi is not None:
                for value in phi.entries.values():
                    if value is not None and value is not phi.dest:
                        worklist.append(id(value))
        return live

    def _remove_dead_phis(self, blocks: list[Block]) -> bool:
        live = self._live_phi_dests(blocks)
        changed = False
        for block in blocks:
            for phi in list(block.phis):
                if id(phi.dest) not in live:
                    block.phis.remove(phi)
                    changed = True
        return changed

    def _remove_trivial_phis(self, blocks: list[Block]) -> bool:
        representative: dict[Temp, Temp] = {}

        def canonical(value: Temp) -> Temp:
            seen = set()
            while value in representative and id(value) not in seen:
                seen.add(id(value))
                value = representative[value]
            return value

        for block in blocks:
            for phi in list(block.phis):
                incoming = {
                    canonical(value)
                    for value in phi.entries.values()
                    if value is not None and value is not phi.dest
                }
                if len(incoming) == 1:
                    replacement = next(iter(incoming))
                    representative[phi.dest] = replacement
                    block.phis.remove(phi)
                    self._replace(blocks, phi.dest, replacement)
                    return True
        return False

    def _replace(self, blocks: list[Block], old: Temp, new: Temp) -> None:
        def subst(value):
            return new if value is old else value

        for block in blocks:
            for phi in block.phis:
                phi.entries = {
                    pred: subst(value) for pred, value in phi.entries.items()
                }
            for ins in block.instructions:
                _map_operands(ins, subst)
            _map_term_operands(block.terminator, subst)

    # -- canonical numbering ----------------------------------------------

    def _renumber(
        self, params: list[Parameter], blocks: list[Block]
    ) -> None:
        """Assign deterministic per-function SSA ids in place.

        Parameters take ids first in parameter order; within each block
        (visited in id order) phi results precede ordinary instruction
        results.  Everything after renumbering refers to the new temps.
        """
        number: dict[Temp, Temp] = {}
        next_id = 0

        def assign(temp: Temp) -> Temp:
            nonlocal next_id
            mapped = number.get(temp)
            if mapped is None:
                mapped = Temp(next_id, temp.type)
                next_id += 1
                number[temp] = mapped
            return mapped

        for param in params:
            param.temp = assign(param.temp)

        for block in blocks:
            for phi in block.phis:
                assign(phi.dest)
            for ins in block.instructions:
                assign(ins.dest)

        def numbered(value):
            if value is None:
                return None
            mapped = number.get(value)
            if mapped is None:
                # Defensive: an operand with no reachable definition.
                # Never occurs for lowered, pruned IR.
                mapped = assign(value)
            return mapped

        for block in blocks:
            for phi in block.phis:
                dest = numbered(phi.dest)
                phi.entries = {
                    pred: numbered(value)
                    for pred, value in sorted(
                        phi.entries.items(), key=lambda item: item[0].id
                    )
                }
                phi.dest = dest
            for ins in block.instructions:
                ins.dest = numbered(ins.dest)
                _map_operands(ins, numbered)
            _map_term_operands(block.terminator, numbered)


# --------------------------------------------------------------------------
# Idempotent cloning of an already-SSA module
# --------------------------------------------------------------------------


def _clone_ssa_module(module: Module) -> Module:
    return Module(
        [_clone_ssa_function(func) for func in module.functions], ssa=True
    )


def _clone_ssa_function(func: Function) -> Function:
    new_blocks = [Block(block.id) for block in func.blocks]
    block_map = dict(zip(func.blocks, new_blocks))

    number: dict[Temp, Temp] = {}
    next_id = 0

    def assign(temp: Temp) -> Temp:
        nonlocal next_id
        mapped = number.get(temp)
        if mapped is None:
            mapped = Temp(next_id, temp.type)
            next_id += 1
            number[temp] = mapped
        return mapped

    new_params: list[Parameter] = []
    for param in func.params:
        new_params.append(
            Parameter(param.name, param.slot, assign(param.temp))
        )
    for block, new_block in zip(func.blocks, new_blocks):
        for phi in block.phis:
            assign(phi.dest)
        for ins in block.instructions:
            assign(ins.dest)

    def ref(value):
        return number[value] if value is not None else None

    for block, new_block in zip(func.blocks, new_blocks):
        for phi in block.phis:
            entries = {
                block_map[pred]: ref(value)
                for pred, value in sorted(
                    phi.entries.items(), key=lambda item: item[0].id
                )
            }
            new_block.phis.append(Phi(ref(phi.dest), entries))
        for ins in block.instructions:
            if isinstance(ins, Const):
                clone = Const(ref(ins.dest), ins.value)
            elif isinstance(ins, Copy):
                clone = Copy(ref(ins.dest), ref(ins.src))
            elif isinstance(ins, BinOp):
                clone = BinOp(
                    ref(ins.dest), ins.operator, ref(ins.left),
                    ref(ins.right), ins.kind, ins.type,
                )
            else:
                clone = Call(
                    ref(ins.dest), ins.name,
                    [ref(arg) for arg in ins.args], ins.type,
                )
            new_block.instructions.append(clone)
        term = block.terminator
        if isinstance(term, Return):
            new_block.terminator = Return(ref(term.value))
        elif isinstance(term, Jump):
            new_block.terminator = Jump(block_map[term.target])
        elif isinstance(term, Branch):
            new_block.terminator = Branch(
                ref(term.cond),
                block_map[term.true_target],
                block_map[term.false_target],
            )

    return Function(
        func.name,
        new_params,
        func.ret_type,
        list(func.locals),
        new_blocks,
        block_map[func.entry],
        ssa=True,
    )

"""Deterministic plain-text rendering of the IR.

The output is a direct, fixed-order walk of the IR tree: functions in
module order, blocks in id order, phi nodes (SSA only) then instructions in
emission order.  Nothing is sorted by name or derived from object identity
-- phi entries are ordered by predecessor label, which is itself fixed -- so
a given module renders byte-identically across processes and repeated
conversions.

Non-SSA modules render exactly as before (``%tN`` temporaries, ``%vN``
slots).  SSA modules use a distinct representation: every value is a unique
``%N`` definition, parameters are rendered with their SSA value, no locals
section is emitted, and phi lines carry the result type plus one
``[block, value]`` pair per reachable predecessor.
"""
from .ir_nodes import (
    BinOp,
    Branch,
    Call,
    Const,
    Copy,
    Function,
    Jump,
    Module,
    Phi,
    Return,
)


def _render_instruction(ins, value) -> str:
    if isinstance(ins, Const):
        literal = "true" if ins.value is True else "false" if ins.value is False else str(ins.value)
        return f"    {value(ins.dest)}: {ins.dest.type} = const {literal}"
    if isinstance(ins, Copy):
        return f"    {value(ins.dest)}: {ins.dest.type} = copy {value(ins.src)}"
    if isinstance(ins, BinOp):
        return (
            f"    {value(ins.dest)}: {ins.type} = {ins.kind} {ins.operator} "
            f"{value(ins.left)} {value(ins.right)}"
        )
    if isinstance(ins, Call):
        args = ", ".join(value(a) for a in ins.args)
        return f"    {value(ins.dest)}: {ins.type} = call {ins.name}({args})"
    raise AssertionError(f"unknown instruction: {ins!r}")  # pragma: no cover


def _render_phi(phi: Phi, value) -> str:
    sources = ", ".join(
        f"[{block.label}, {value(val)}]"
        for block, val in sorted(phi.entries.items(), key=lambda item: item[0].id)
    )
    return f"    {value(phi.dest)}: {phi.type} = phi {sources}"


def _render_terminator(term, value) -> str:
    if isinstance(term, Return):
        if term.value is None:
            return "    return"
        return f"    return {value(term.value)}"
    if isinstance(term, Jump):
        return f"    jump {term.target.label}"
    if isinstance(term, Branch):
        return (
            f"    br {value(term.cond)}, {term.true_target.label}, "
            f"{term.false_target.label}"
        )
    raise AssertionError(f"unknown terminator: {term!r}")  # pragma: no cover


def _render_function(func: Function) -> str:
    ssa = getattr(func, "ssa", False)

    if ssa:
        def value(v) -> str:
            return f"%{v.id}"

        params = ", ".join(
            f"{p.name}: {p.temp.type} @ {value(p.temp)}" for p in func.params
        )
    else:
        def value(v) -> str:
            return str(v)

        params = ", ".join(f"{p.name}: {p.slot.type} @ {value(p.slot)}"
                           for p in func.params)

    lines = [f"function {func.name}({params}) -> {func.ret_type} {{"]
    if not ssa and func.locals:
        lines.append("  locals:")
        for slot in func.locals:
            lines.append(f"    {value(slot)}: {slot.type}")
    for block in func.blocks:
        lines.append(f"  {block.label}:")
        if ssa:
            for phi in block.phis:
                lines.append(_render_phi(phi, value))
        for ins in block.instructions:
            lines.append(_render_instruction(ins, value))
        lines.append(_render_terminator(block.terminator, value))
    lines.append("}")
    return "\n".join(lines)


def render_module(module: Module) -> str:
    """Render a :class:`Module` to deterministic plain text."""
    parts = ["module"]
    parts.extend(_render_function(func) for func in module.functions)
    return "\n".join(parts) + "\n"

"""Tests for the non-SSA -> pruned SSA conversion (:func:`to_ssa`).

The tests pin down: unique definitions and slot elimination; phi placement
at real joins (if/else, missing else, nesting, loop headers, short-circuit
merges); phi ordering and reachable-only predecessors; redundant-phi
pruning; preservation of calls, arithmetic, comparisons, branches and
return values; deterministic per-function numbering; byte-identical
idempotence; ``TypeError`` for non-modules; and full compatibility of the
existing non-SSA pipeline.
"""
import unittest

from compiler_ir import (
    BinOp,
    Branch,
    Call,
    Copy,
    Jump,
    Module,
    Phi,
    Return,
    Slot,
    Temp,
    emit_ir,
    lower_module,
    render_module,
    to_ssa,
)

from test_pipeline import (
    arith,
    assign,
    bool_,
    call,
    compare,
    func,
    if_,
    int_,
    let,
    logical,
    param,
    program,
    ret,
    var,
    while_,
)


# --------------------------------------------------------------------------
# Structural helpers
# --------------------------------------------------------------------------


def _edges(block):
    term = block.terminator
    if isinstance(term, Jump):
        return [term.target]
    elif isinstance(term, Branch):
        return [term.true_target, term.false_target]
    return []


def _operands(ins):
    if isinstance(ins, Copy):
        return [ins.src]
    if isinstance(ins, BinOp):
        return [ins.left, ins.right]
    if isinstance(ins, Call):
        return list(ins.args)
    return []


def _reachable(func):
    seen = {func.entry}
    stack = [func.entry]
    while stack:
        block = stack.pop()
        for target in _edges(block):
            if target not in seen:
                seen.add(target)
                stack.append(target)
    return seen


def _predecessors(func):
    reach = _reachable(func)
    preds = {block: [] for block in func.blocks}
    for block in func.blocks:
        if block in reach:
            for target in _edges(block):
                if target in reach:
                    preds[target].append(block)
    return preds, reach


def _all_values(func):
    """Every operand value appearing anywhere in a function."""
    values = []
    for block in func.blocks:
        for phi in block.phis:
            values.extend(phi.entries.values())
        for ins in block.instructions:
            values.extend(_operands(ins))
        term = block.terminator
        if isinstance(term, Return):
            if term.value is not None:
                values.append(term.value)
        elif isinstance(term, Branch):
            values.append(term.cond)
    return values


def _defined_temps(func):
    """Every definition, in canonical order (params, phis, instructions)."""
    defs = [p.temp for p in func.params]
    for block in func.blocks:
        defs.extend(phi.dest for phi in block.phis)
        defs.extend(ins.dest for ins in block.instructions)
    return defs


def assert_ssa_well_formed(test, func):
    preds, reach = _predecessors(func)

    # Every definition is a Temp with a unique, dense per-function id.
    defs = _defined_temps(func)
    ids = [d.id for d in defs]
    test.assertEqual(sorted(ids), list(range(len(ids))))
    test.assertFalse(any(isinstance(d, Slot) for d in defs))

    defblock = {}
    for param in func.params:
        defblock[id(param.temp)] = func.entry
    for blk in func.blocks:
        for phi in blk.phis:
            defblock[id(phi.dest)] = blk
        for ins in blk.instructions:
            defblock[id(ins.dest)] = blk

    # Every use is a defined Temp (no Slots), and phis sit before ordinary
    # instructions with exactly the reachable predecessors, in label order.
    for blk in func.blocks:
        if blk not in reach:
            continue
        for phi in blk.phis:
            keys = list(phi.entries.keys())
            test.assertEqual(
                [k.id for k in keys], sorted(k.id for k in keys)
            )
            test.assertEqual(set(keys), set(preds[blk]))
            for value in phi.entries.values():
                test.assertIsInstance(value, Temp)
                test.assertIn(id(value), defblock)
        for value in _all_values(func):
            test.assertIsInstance(value, Temp)
            test.assertIn(id(value), defblock)
        test.assertEqual(
            [type(i) for i in blk.instructions].count(Phi), 0
        )


